using Kitsuneo.Core.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Kitsuneo.Infrastructure.Persistence.Configurations;

public class PhraseConfiguration : IEntityTypeConfiguration<Phrase>
{
    public void Configure(EntityTypeBuilder<Phrase> builder)
    {
        builder.ToTable("phrases");

        builder.HasKey(p => p.Id);

        // The Id is generated by the domain (Guid v7) in Phrase.Create
        builder.Property(p => p.Id)
            .ValueGeneratedNever();

        builder.Property(p => p.UserId)
            .IsRequired();

        // Stored as text through the enum convention in AppDbContext
        builder.Property(p => p.Language)
            .IsRequired();

        builder.Property(p => p.Text)
            .HasMaxLength(Phrase.MaxLength)
            .IsRequired();

        builder.Property(p => p.SpokenForm)
            .HasMaxLength(Phrase.MaxLength)
            .IsRequired();

        builder.Property(p => p.Reading)
            .HasMaxLength(Phrase.MaxLength);

        builder.Property(p => p.Translation)
            .HasMaxLength(Phrase.MaxLength);

        builder.Property(p => p.IsArchived)
            .IsRequired();

        builder.Property(p => p.CreatedAt)
            .IsRequired();

        // Serve the list query: filter by user (and language), ordered by (CreatedAt, Id) for keyset pagination
        builder.HasIndex(p => new { p.UserId, p.CreatedAt, p.Id })
            .HasFilter("\"IsArchived\" = false");

        builder.HasIndex(p => new { p.UserId, p.Language, p.CreatedAt, p.Id })
            .HasFilter("\"IsArchived\" = false");
    }
}
